public static class UsabilityTests {
 static readonly string Root=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../.."));
 static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}
 static void Wait(Func<bool> value,int seconds=25){var until=DateTime.UtcNow.AddSeconds(seconds);while(!value()){if(DateTime.UtcNow>until)throw new Exception("Experience state timed out");Pump();Thread.Sleep(15);}}
 static void Await(Task task){Wait(()=>task.IsCompleted);task.GetAwaiter().GetResult();Pump();}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);}
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(root,i)))yield return child;}
 static void Enter(TextBox input){input.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(input),0,Key.Enter){RoutedEvent=UIElement.KeyDownEvent});}
 static void Pick(MainWindow owner,Action show,string query,Action<ListBox> inspect){Exception failure=null;bool finished=false;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(25)};timer.Tick+=delegate{Window dialog=Application.Current.Windows.Cast<Window>().LastOrDefault(w=>w!=owner&&w.Owner==owner&&w.IsVisible);if(dialog==null)return;timer.Stop();try{dialog.UpdateLayout();var input=Walk(dialog).OfType<TextBox>().First();input.Text=query;Pump();inspect(Walk(dialog).OfType<ListBox>().First());Enter(input);}catch(Exception e){failure=e;dialog.Close();}finally{finished=true;}};timer.Start();try{show();Wait(()=>finished);}finally{timer.Stop();}if(failure!=null)throw failure;Pump();}
 static void Close(MainWindow window){foreach(var doc in window.Session.Documents)if(window.buffers.ContainsKey(doc))window.buffers[doc].UndoStack.MarkAsOriginalFile();window.Close();Wait(()=>!Application.Current.Windows.Cast<Window>().Contains(window));}
 static void Capture(MainWindow owner,string name){Window window=owner.OwnedWindows.Cast<Window>().LastOrDefault(w=>w.IsVisible)??owner;window.UpdateLayout();Pump();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var visual=new DrawingVisual();using(var drawing=visual.RenderOpen()){drawing.DrawImage(bitmap,new Rect(0,0,window.ActualWidth,window.ActualHeight));var browser=window==owner?owner.terminalPanel.Browser:null;if(browser!=null&&browser.CoreWebView2!=null)using(var stream=new MemoryStream()){Await(browser.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,stream));stream.Position=0;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();var origin=browser.TranslatePoint(new Point(),window);drawing.DrawImage(image,new Rect(origin.X,origin.Y,browser.ActualWidth,browser.ActualHeight));}}var full=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);full.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(full));using(var file=File.Create(Path.Combine(Root,"artifacts/ui/",name)))encoder.Save(file);}
 static Dictionary<string,object> State(TerminalPanel panel){var task=panel.StateAsync();Await(task);return task.Result;}
 static string Script(TerminalPanel panel,string code){var task=panel.Browser.CoreWebView2.ExecuteScriptAsync(code);Await(task);return task.Result;}
 static void TerminalText(TerminalPanel panel,string value){Wait(()=>{var state=State(panel);return state.ContainsKey("text")&&Convert.ToString(state["text"]).Contains(value);});}
 [STAThread]public static int Main(string[] args){
  if(args.Length==2&&args[0]=="draft-fixture"){var drafts=new DraftStore(args[1]);drafts.Write(new[]{new DraftItem{Id="crash-fixture",Title="synthetic.txt",OriginalPath=Path.Combine(args[1],"original.txt"),Text="RECOVERED_SYNTHETIC_TEXT",EncodingName="utf-8",NewLine="\r\n"}});Environment.Exit(0);}
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));string root=Path.GetFullPath(Path.Combine(Root,"build/ux-tests-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(Root,"artifacts/ui"));MainWindow window=null;
  try{
   MainWindow.UsageRootOverride=Path.Combine(root,"default-state");window=new MainWindow{ShowActivated=false,Left=-16000,Top=0};window.Show();Pump();Check(!Directory.Exists(MainWindow.UsageRootOverride)&&window.terminalPanel.Browser==null,"Default startup creates no usage directory and no browser");Check(Walk(window).OfType<TextBlock>().Any(t=>t.IsVisible&&t.Text.Contains("打开一份文件")),"Blank document shows native start hints");Capture(window,"experience-0.14-start.png");
   window.TestHooks.Toolbar.saveDropdown.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(window.SaveButton.ContextMenu.IsOpen,"Left-click save arrow opens export/save menu");Capture(window,"experience-0.14-save.png");window.SaveButton.ContextMenu.IsOpen=false;
   string a=Path.Combine(root,"first.txt"),b=Path.Combine(root,"second.txt");File.WriteAllText(a,String.Join("\n",Enumerable.Range(0,400).Select(i=>"line "+i)));File.WriteAllText(b,"SECOND_FILE_UNCHANGED");
   var active=window;Pick(window,()=>QuickOpen.Show(active),"\""+a+"\"",list=>{Check(list.Items.Count==1,"Full path outside a workspace is an explicit open action");Capture(active,"experience-0.14-path.png");});Wait(()=>window.Current.Path==a);
   var first=window.Current;window.ActiveEditor.CaretOffset=34;window.ActiveEditor.ScrollToVerticalOffset(200);Pump();Await(window.OpenPathsAsync(new[]{b},true));var second=window.Current;Check(window.ActiveEditor.CaretOffset==0,"Batch/opening a different file does not inherit another file's caret");window.SelectDocument(first,null);Check(window.ActiveEditor.CaretOffset==34,"Switching files restores the original caret");window.CloseTab(first);Await(window.Usage.ReopenAsync());Check(window.Current.Path==a&&window.ActiveEditor.CaretOffset==34,"Ctrl+Shift+T action reopens the saved file and caret");
   var before=window.Usage.PositionOf(window.Current);string savedAs=Path.Combine(root,"saved-as.txt");File.Copy(a,savedAs);window.Current.Path=savedAs;window.Usage.Saved(window.Current,before);Check(window.ActiveEditor.CaretOffset==34,"Saving to a new path migrates the caret instead of resetting it");
   Pick(window,()=>QuickOpen.ShowCommands(active),"双文件分栏",list=>{Check(list.Items.Count==1,"Chinese command query finds the intended command");Capture(active,"experience-0.14-commands.png");});Wait(()=>window.Appearance.Layout=="compare");Check(window.terminalPanel.Browser==null,"Command palette does not initialize a browser");window.SetLayout("single");
   window.search.Show(false);Check(!window.search.ReplaceVisible,"Ctrl+F shows compact find without replacement");window.search.Show(true);Check(window.search.ReplaceVisible,"Ctrl+H expands replacement");window.search.ToggleSearch();window.Width=390;window.Height=640;window.UpdateToolbar();Capture(window,"experience-0.14-narrow.png");Exception settingError=null;Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Loaded,new Action(delegate{Window dialog=null;try{dialog=Application.Current.Windows.Cast<Window>().Last(w=>w!=active&&w.Owner==active);dialog.UpdateLayout();var choices=Walk(dialog).OfType<CheckBox>().ToArray();Check(choices.Length==3&&choices.All(c=>c.IsChecked!=true),"Local record switches are independent and default off");Capture(active,"experience-0.14-settings.png");}catch(Exception e){settingError=e;}finally{if(dialog!=null)dialog.Close();}}));window.ShowPrivacySettings();if(settingError!=null)throw settingError;Check(!Directory.Exists(MainWindow.UsageRootOverride),"Viewing local-record settings does not enable persistence");window.Width=1240;window.Height=820;
   window.ToggleTerminal();Wait(()=>window.terminalPanel.IsRunning||window.terminalPanel.RendererError!=null);Check(window.terminalPanel.IsRunning,"Terminal starts with the search extension available");var panel=window.terminalPanel;panel.Send("echo QY_NEEDLE one QY_NEEDLE\r");TerminalText(panel,"QY_NEEDLE one");panel.Find();Wait(()=>Convert.ToBoolean(State(panel)["searchVisible"]));Script(panel,"(()=>{const input=document.querySelector('.terminal-find input');input.value='QY_NEEDLE';input.dispatchEvent(new Event('input',{bubbles:true}));})()");Wait(()=>{var state=State(panel);var result=state["searchResults"] as Dictionary<string,object>;return result!=null&&Convert.ToInt32(result["resultCount"])>=2;});Check(true,"Terminal search finds real output and reports a result count");Capture(window,"experience-0.14-terminal-find.png");Script(panel,"document.querySelector('.terminal-find input').dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");Check(!Convert.ToBoolean(State(panel)["searchVisible"]),"Escape closes terminal find without sending it as shell input");panel.Send("for /L %i in (1,1,120) do @echo UX_SCROLL_%i\r");TerminalText(panel,"UX_SCROLL_120");panel.Find();Wait(()=>Convert.ToBoolean(State(panel)["searchVisible"]));Script(panel,"(()=>{const input=document.querySelector('.terminal-find input');input.value='Microsoft';input.dispatchEvent(new Event('input',{bubbles:true}));})()");Wait(()=>Convert.ToInt32(State(panel)["viewportY"])<Convert.ToInt32(State(panel)["baseY"]));Script(panel,"document.querySelector('.terminal-find input').dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");panel.Bottom();Wait(()=>Convert.ToInt32(State(panel)["viewportY"])==Convert.ToInt32(State(panel)["baseY"]));Check(true,"Back-to-bottom restores the latest output after scrolling history");Close(window);window=null;Check(!Directory.Exists(MainWindow.UsageRootOverride),"Default file operations and terminal leave no usage history on disk");
   string history=Path.Combine(root,"remembered");var store=new UsageStore(history);store.SaveOptions(new UsageOptions{RecentFiles=true,ReadingPositions=true});MainWindow.UsageRootOverride=history;window=new MainWindow{ShowActivated=false,Left=-16000};window.Show();Await(window.OpenPathsAsync(new[]{a},false));window.ActiveEditor.CaretOffset=44;window.Usage.Capture();window.Usage.Persist();Await(window.Usage.Pending);Close(window);window=null;window=new MainWindow{ShowActivated=false,Left=-16000};window.Show();Await(window.OpenPathsAsync(new[]{a},false));Check(window.ActiveEditor.CaretOffset==44,"Opt-in caret position survives a new window");var stale=store.LoadEntries();store.Clear();store.Remember(stale);Check(store.LoadEntries().Count==0,"Cleared metadata cannot be revived by an old window cache");Close(window);window=null;
   string markdown=Path.Combine(root,"reading.md");File.WriteAllText(markdown,String.Join("\n\n",Enumerable.Range(0,160).Select(i=>"## Chapter "+i+"\n\nParagraph content "+i)));window=new MainWindow{ShowActivated=false,Left=-16000};window.Show();Await(window.OpenPathsAsync(new[]{markdown},false));window.SetViewMode("reader");Await(window.UpdatePreviewAsync());window.UpdateLayout();window.preview.RestoreReadingOffset(500);Wait(()=>window.preview.ReadingOffset>400);window.Usage.Capture();window.Usage.Persist();Await(window.Usage.Pending);Close(window);window=null;window=new MainWindow{ShowActivated=false,Left=-16000};window.Show();Await(window.OpenPathsAsync(new[]{markdown},false));Wait(()=>window.preview.ReadingOffset>400);Check(true,"Opt-in native Markdown reading position survives a new window");Close(window);window=null;
   string recovery=Path.Combine(root,"recovery");Directory.CreateDirectory(recovery);File.WriteAllText(Path.Combine(recovery,"original.txt"),"ORIGINAL_UNCHANGED");using(var fixture=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"draft-fixture \""+recovery+"\""){UseShellExecute=false,CreateNoWindow=true})){Check(fixture.WaitForExit(10000)&&fixture.ExitCode==0,"Recovery fixture exits without normal draft cleanup");}Check(new DraftStore(recovery).Pending().Count==1,"Draft is recoverable after its process has exited");new UsageStore(recovery).SaveOptions(new UsageOptions{RecoverDrafts=true});MainWindow.UsageRootOverride=recovery;window=new MainWindow{ShowActivated=false,Left=-16000};window.Show();active=window;Pick(window,()=>active.Usage.ShowRecovery(),"synthetic",list=>Check(list.Items.Count==1,"Recovery lists the pending draft"));Wait(()=>window.ActiveEditor.Text=="RECOVERED_SYNTHETIC_TEXT");Await(window.Usage.Pending);Check(window.Current.Path==null&&window.Current.IsDirty&&File.ReadAllText(Path.Combine(recovery,"original.txt"))=="ORIGINAL_UNCHANGED","Recovery creates an unsaved copy and preserves the original file");Check(new DraftStore(recovery).Pending().Count==0,"Recovered pending draft is consumed while active draft stays isolated");new UsageStore(recovery).SaveOptions(new UsageOptions());window.ActiveEditor.AppendText(" CHANGED_AFTER_GLOBAL_DISABLE");window.Usage.Snapshot();Await(window.Usage.Pending);Check(Directory.GetFiles(Path.Combine(recovery,"drafts"),"*.json").Length==0,"Another window disabling recovery prevents stale options from writing drafts");Close(window);window=null;Check(new DraftStore(recovery).Pending().Count==0,"Normal close clears this window's recovery data");
   Console.WriteLine("Usability acceptance passed");return 0;
  }catch(Exception error){Console.WriteLine("FAIL "+error);if(window!=null){Console.WriteLine("CURRENT "+window.Current.Path);Console.WriteLine("NOTICE "+window.TestHooks.Footer.notice.Text);Console.WriteLine("DOCS "+String.Join(";",window.Session.Documents.Select(d=>d.Path??"blank")));}return 1;}finally{if(window!=null)Close(window);MainWindow.UsageRootOverride=null;app.Shutdown();}
 }
